import re

def redact_unsafe(text: str, unsafe_pattern: str = r"\b(?:racist|sexist|profane)\b", replacement: str = "[REDACTED]") -> str:
    """Flag or redact unsafe word spans from text.

    Uses a simple regex pattern (can be replaced with a more sophisticated model).
    Returns the text with unsafe tokens replaced by the replacement string.
    """
    # The pattern can be extended to include more unsafe terms or generated by a model.
    return re.sub(unsafe_pattern, replacement, text, flags=re.IGNORECASE)
